// India Map Vector Coordinates and Cities Data

export interface CityCoord {
  name: string;
  state: string;
  lat: number;
  lon: number;
  desc: string;
  svgX: number;
  svgY: number;
  normX: number;
  normY: number;
}

export interface StateBoundary {
  name: string;
  d: string;
}

const WIDTH = 760;
const HEIGHT = 870;
const MIN_LON = 68;
const MAX_LON = 97.5;
const MIN_LAT = 6.5;
const MAX_LAT = 37.2;
const PAD_X = 25;
const PAD_Y = 25;
const DRAW_W = 710;
const DRAW_H = 820;

function project(lon: number, lat: number): [number, number] {
  const xNorm = (lon - MIN_LON) / (MAX_LON - MIN_LON);
  const yNorm = (MAX_LAT - lat) / (MAX_LAT - MIN_LAT);
  const px = PAD_X + xNorm * DRAW_W;
  const py = PAD_Y + yNorm * DRAW_H;
  return [px, py];
}

function unproject(normX: number, normY: number): [number, number] {
  const px = normX * WIDTH;
  const py = normY * HEIGHT;
  const xNorm = (px - PAD_X) / DRAW_W;
  const yNorm = (py - PAD_Y) / DRAW_H;
  const lon = MIN_LON + xNorm * (MAX_LON - MIN_LON);
  const lat = MAX_LAT - yNorm * (MAX_LAT - MIN_LAT);
  return [lon, lat];
}

// Earth distance formula in Kilometers (Haversine)
function haversineKm(
  lat1: number,
  lon1: number,
  lat2: number,
  lon2: number,
): number {
  const R = 6371; // km
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.cos((lat1 * Math.PI) / 180) *
      Math.cos((lat2 * Math.PI) / 180) *
      Math.sin(dLon / 2) *
      Math.sin(dLon / 2);
  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
  return Math.round(R * c);
}

