function getCityInfo(cityName: string | null | undefined): CityCoord {
  if (!cityName) return CITIES["nagpur"];
  const key = cityName.toLowerCase().trim();
  if (CITIES[key]) return CITIES[key];
  for (const k in CITIES) {
    if (
      CITIES[k].name.toLowerCase() === key ||
      key.includes(k) ||
      k.includes(key)
    ) {
      return CITIES[k];
    }
  }
  // Default fallback to Nagpur, Zero Mile epicenter of India
  return CITIES["nagpur"];
}

